const http = require('http');

const data = JSON.stringify({
  lead: {
    id: '123',
    full_name: 'Test Name',
    email: 'neha.ci22@bmsce.ac.in',
    phone: '123456',
    country: 'India',
    treatment_interest: 'Dental',
    preferred_date: '2026-05-01',
    urgency: 'Standard',
    message: 'Hello'
  },
  pdf_base64: ''
});

const options = {
  hostname: 'localhost',
  port: 3001,
  path: '/api/send-email',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': data.length
  }
};

const req = http.request(options, res => {
  console.log(`statusCode: ${res.statusCode}`);
  let responseBody = '';
  
  res.on('data', chunk => {
    responseBody += chunk;
  });
  
  res.on('end', () => {
    console.log('Response:', responseBody);
  });
});

req.on('error', error => {
  console.error('Request error:', error);
});

req.write(data);
req.end();
